// Участок 45, линия A. Два дня с Нильсом по деревням Эльбмарша: попутчик у Луэ, трактор на дамбе, раздача в Теспе (посылок
// меньше, чем людей), старики Фоккен на дамбе (Гезине нужна колонна, Тамме не уедет), обед в кабине, низина у Драге — сеновал
// с Феньей и детьми через замёрзшую канаву с мёртвыми во льду, ночь в пожарной части у Бернда. Четверг: паром в Хоопте — два
// последних места колонны (один, если записали Гезину), снова дамба, Нильс зовёт вторым водителем, Йестебург, хутор к 15:00.
const X = (scene: Omit<Scene, 'for' | 'chapter'>): Scene => S45({ ...scene, for: 'any', chapter: 'ch3' });
const M = (scene: Omit<Scene, 'for' | 'chapter' | 'location'>): Scene => X({ ...scene, location: marsch45, camp: scene.camp ?? trip45(marsch45), safe: false });
const D = (scene: Omit<Scene, 'for' | 'chapter' | 'location'>): Scene => X({ ...scene, location: drage45, camp: scene.camp ?? trip45(drage45, 'sleep'), safe: true });
const toMarsch: Effect = { move: marsch45 };
const toDrage: Effect = { move: drage45 };
const toJest: Effect = { move: jest45 };
const toFarm: Effect = { move: farm45 };
const bruise: Effect[] = [{ injure: 'bruise', site: 'leftLeg', severity: 2 }, { body: 'stress', delta: 4 }];
const gesinaListed: Cond = v('w.c45_fokken', 'listed');
const hiker: Cond = any(own45('hk', 'take'), own45('hk', 'check'));
const station = { tempC: 16, outdoor: false, wet: false };
const eelTo = (n: number): Effect[] => [{ take: 'c45_eel', qty: n }, { place: 'c45_eel', at: 'c3_farm_stock', qty: n }];
/** Все угри, что при себе, — в кладовую хутора (их бывает от одного до трёх). */
const eelHome: Effect[] = [{ if: { has: 'c45_eel', qty: 3 }, then: eelTo(3), else: [{ if: { has: 'c45_eel', qty: 2 }, then: eelTo(2), else: eelTo(1) }] }];

